19	    private final SeenStore seenStore;
20	    private final AgentToolLoop toolLoop;
21	    private final AuditLog auditLog;
22	
23	    public MailProcessingService(MailChannel mailChannel, SeenStore seenStore, AgentToolLoop toolLoop) {
24	        this(mailChannel, seenStore, toolLoop, null);
