39	            log.warn("mail_channel_error: failed to fetch unread messages", e);
40	            appendAudit(LogEvents.MAIL_CHANNEL_ERROR, "{\"stage\":\"fetchUnread\"}");
41	            return;
42	        }
43	
44	        for (Msg msg : unread) {
45	            if (!seenStore.markIfNew(msg.getId())) {
46	                continue;
47	            }
48	            appendAudit(LogEvents.AGENT_MAIL_SEEN, "{\"messageId\":\"" + LogEvents.jsonEscape(msg.getId()) + "\"}");
49	
50	            String reply;
51	            try {
52	                reply = toolLoop.run(msg.getBody());
53	            } catch (LlmException e) {
54	                seenStore.unmark(msg.getId());
55	                log.warn("llm_failed: could not obtain a reply from the LLM, will retry on next cycle", e);
56	                appendAudit(LogEvents.LLM_FAILED, "{\"messageId\":\"" + LogEvents.jsonEscape(msg.getId()) + "\"}");
57	                continue;
58	            }
59	
60	            try {
61	                mailChannel.reply(msg, reply);
62	            } catch (MailChannelException e) {
63	                seenStore.unmark(msg.getId());
64	                log.warn("mail_channel_error: failed to send reply, will retry on next cycle", e);
65	                appendAudit(LogEvents.MAIL_CHANNEL_ERROR, "{\"stage\":\"reply\",\"messageId\":\""
66	                        + LogEvents.jsonEscape(msg.getId()) + "\"}");
67	                continue;
68	            }
69	            appendAudit(LogEvents.AGENT_REPLY_SENT, "{\"messageId\":\"" + LogEvents.jsonEscape(msg.getId()) + "\"}");
70	        }
71	    }
72	
